#!/bin/bash
set -e

echo "=================================================="
echo " Deploy: Refraction Type of Glass, column widths,"
echo " darker print text, doctor signature space"
echo "=================================================="
echo ""
echo "OPD Case Sheet changes:"
echo "1) TYPE OF GLASS line added below the Refraction"
echo "   table (same as the Spectacle Prescription printout)"
echo "2) Refraction table: label column (Dist./NEAR ADD)"
echo "   widened to 90px; the 10 data columns (SPH/CYL/AXIS/"
echo "   PRISM/VISION x2 eyes) narrowed to 8% each"
echo "3) Text darkened for print contrast: base text color"
echo "   #1a1a1a -> pure #000; muted label grays #444/#666"
echo "   -> #222/#333"
echo "4) Doctor signature: blank space + a signature line"
echo "   added above the doctor's name at the bottom"
echo ""

TARGET="app/print-templates/actions.js"

if [ ! -f "$TARGET" ]; then
  echo "ERROR: $TARGET not found. Run this script from the repo root."
  exit 1
fi

echo "Backing up current file to $TARGET.bak ..."
cp "$TARGET" "$TARGET.bak"

echo "Writing updated $TARGET ..."
echo "" | base64 -d > "$TARGET"

echo ""
echo "Verifying JS syntax ..."
node --check "$TARGET" && echo "  Syntax OK"

echo ""
echo "Done. Review the diff with:"
echo "  git diff $TARGET"
echo ""
echo "NOTE: if OPD Case Sheet has ever been customized via the"
echo "in-app Print Templates editor, that saved version"
echo "overrides this code default -- reset it from that admin"
echo "page on both production and training for this to take"
echo "effect."
